fast_pseudocode:
# CORRECT: grid must use meta['XBLOCK'] to adapt to autotuned tile size
@triton.autotune(configs=[Config({'XBLOCK': 256}), Config({'XBLOCK': 512}), ...], key=['xnumel'])
@triton.jit
def kernel(ptr, xnumel, XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    ...

# Launch with DYNAMIC grid — scales correctly with XBLOCK
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](ptr, xnumel)  # grid shrinks as XBLOCK grows

